import * as T from 'three';
import{seeded}from'./geometry.js';
export function createMaterials(renderer){
 const{random,rr}=seeded(1855),textures=[];
 function canvas(w,h,paint,color=true){const c=document.createElement('canvas');c.width=w;c.height=h;paint(c.getContext('2d'),w,h);const t=new T.CanvasTexture(c);if(color)t.colorSpace=T.SRGBColorSpace;t.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());textures.push(t);return t;}
 const brick=canvas(512,512,(c,w,h)=>{c.fillStyle='#836257';c.fillRect(0,0,w,h);for(let row=0;row<32;row++)for(let col=-1;col<9;col++){c.fillStyle=`hsl(${rr(10,18)},${rr(38,48)}%,${rr(42,50)}%)`;c.fillRect(col*64+(row%2)*32+1,row*16+1,62,14);}for(let i=0;i<6500;i++){c.fillStyle=random()<.5?'#ffffdd0c':'#271b1712';c.fillRect(rr(0,w),rr(0,h),rr(1,3),rr(1,2));}});brick.wrapS=brick.wrapT=T.RepeatWrapping;brick.repeat.set(1,1);
 const noise=canvas(256,256,(c,w,h)=>{c.fillStyle='#b8b8b8';c.fillRect(0,0,w,h);for(let i=0;i<9000;i++){const v=Math.floor(rr(100,230));c.fillStyle=`rgb(${v},${v},${v})`;c.fillRect(rr(0,w),rr(0,h),rr(.5,2.2),rr(.5,2.2));}},false);noise.wrapS=noise.wrapT=T.RepeatWrapping;noise.repeat.set(5,5);
 const pavement=canvas(1024,1024,(c,w,h)=>{c.fillStyle='#c4cacf';c.fillRect(0,0,w,h);for(let r=0;r<48;r++)for(let j=-1;j<27;j++){const x=j*40+(r%2)*20,y=r*22;const v=rr(163,188);c.fillStyle=`rgb(${v},${v+3},${v+5})`;c.beginPath();c.roundRect(x+1,y+1,38,20,rr(2,5));c.fill();c.strokeStyle='#dce3e3';c.lineWidth=rr(2,5);c.stroke();if(random()<.8){c.fillStyle='#e9edee';c.fillRect(x+2,y+1,36,rr(11,19));}}});pavement.wrapS=pavement.wrapT=T.RepeatWrapping;pavement.repeat.set(3,3);
 const mats=[];function mat(name,color,extra={}){const m=new T.MeshStandardMaterial({color,roughness:.78,...extra});m.name=name;mats.push(m);return m;}
 const M={brick:mat('Moscow red brick','#e2bcb0',{map:brick,bumpMap:brick,bumpScale:.045}),brickDark:mat('Kremlin brick','#b48273',{map:brick,bumpMap:brick,bumpScale:.045}),trim:mat('Warm limestone','#e2cfad',{bumpMap:noise,bumpScale:.013}),white:mat('Carved white stone','#eee6d6',{bumpMap:noise,bumpScale:.008}),stone:mat('Granite embankment','#8a9094',{bumpMap:noise,bumpScale:.04}),stoneDark:mat('Foundation granite','#636b73',{bumpMap:noise,bumpScale:.04}),snow:mat('Fresh snow','#e8eff0',{roughness:.9,bumpMap:noise,bumpScale:.018,roughnessMap:noise}),copper:mat('Patinated green roof','#276d61',{metalness:.35,roughness:.57}),roof:mat('Graphite roof','#3d555d',{metalness:.42,roughness:.52}),gold:mat('Antique gold','#cba954',{metalness:.79,roughness:.3}),iron:mat('Dark wrought iron','#293c42',{metalness:.7,roughness:.43}),wood:mat('Warm oak','#665143',{bumpMap:noise,bumpScale:.025}),dark:mat('Recess shadow','#172a31',{roughness:.92}),pave:mat('Frosted cobblestone','#f3eee8',{map:pavement,bumpMap:pavement,bumpScale:.055,roughness:.76}),road:mat('Wet winter asphalt','#485357',{bumpMap:noise,bumpScale:.012,roughness:.4}),rubber:mat('Tyres and boots','#1c272e',{roughness:.94}),silver:mat('Weathered steel','#a7b1b6',{metalness:.75,roughness:.36}),red:mat('Oxblood paint','#9e3437',{roughness:.35,metalness:.18}),cream:mat('Cream plaster','#d3c4a6'),plaster:mat('Dusty rose plaster','#bf8d7d'),skin:mat('Skin','#caa58c'),fabric:mat('Winter wool','#354e60',{roughness:1}),scarf:mat('Wool scarf','#bd7e54',{roughness:1}),fur:mat('Fur hat','#594c43',{roughness:1}),dome:mat('Enamel dome patterns','#ffffff',{vertexColors:true,metalness:.35,roughness:.4}),glass:mat('Blue smoked glass','#344c59',{metalness:.38,roughness:.2}),window:mat('Lit interior glass','#6d6452',{emissive:'#ffc078',emissiveIntensity:.16,roughness:.28,metalness:.1}),lamp:mat('Warm lantern diffuser','#fce3ad',{emissive:'#ffba65',emissiveIntensity:1.2,roughness:.4})};
 for(const m of[M.window,M.lamp])m.userData.castShadow=false;
 function sign(text,sub='',bg='#233e42',fg='#e6d8b5',w=1024){const map=canvas(w,256,(c)=>{c.fillStyle=bg;c.fillRect(0,0,w,256);c.strokeStyle=fg;c.lineWidth=3;c.strokeRect(10,10,w-20,236);c.fillStyle=fg;c.textAlign='center';c.textBaseline='middle';c.font=`500 ${text.length>20?38:56}px Georgia,serif`;c.fillText(text,w/2,sub?95:128,w-65);if(sub){c.font='23px Arial,sans-serif';c.fillText(sub,w/2,177,w-65);}});return mat('Sign · '+text,'#ffffff',{map,roughness:.7});}
 return{M,mats,textures,canvas,sign,dispose(){mats.forEach(m=>m.dispose());textures.forEach(t=>t.dispose());}};
}
